import { View, Text, FlatList, StyleSheet } from "react-native";
import { registerRootComponent } from "expo";

const PICKS = [
  { id: "p1", name: "Чихэвч" },
  { id: "p2", name: "Гар цаг" },
  { id: "p3", name: "Нарны шил" },
  { id: "p4", name: "Цүнх" },
  { id: "p5", name: "Гутал" },
];

function App() {
  // энд бичнэ үү: FlatList-д horizontal prop нэмж хэвтээ гүйдэг болго
  return (
    <View style={styles.screen}>
      <Text style={styles.title}>Танд санал болгох</Text>
      <FlatList
        data={PICKS}
        keyExtractor={(item) => item.id}
        renderItem={({ item }) => (
          <View testID="card" style={styles.card}>
            <Text style={styles.name}>{item.name}</Text>
          </View>
        )}
      />
    </View>
  );
}

const styles = StyleSheet.create({
  screen: { flex: 1, padding: 16, backgroundColor: "#f8fafc" },
  title: { fontSize: 18, fontWeight: "bold", marginBottom: 12 },
  card: { width: 120, height: 120, marginRight: 12, backgroundColor: "#fff", borderRadius: 12, alignItems: "center", justifyContent: "center", elevation: 2 },
  name: { fontSize: 15, fontWeight: "600" },
});

registerRootComponent(App);

